import{_ as n,C as e,o as r,c as s,E as o,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"TMPA 架构论文 — 学术草稿 A0.5","description":"","frontmatter":{"title":"TMPA 架构论文 — 学术草稿 A0.5","outline":"deep"},"headers":[],"relativePath":"zh/publications/tmpa-architecture-paper-a0.5/part-01.md","filePath":"zh/publications/tmpa-architecture-paper-a0.5/part-01.md","lastUpdated":1786085052000}'),l={name:"zh/publications/tmpa-architecture-paper-a0.5/part-01.md"};function p(d,t,c,g,h,P){const a=e("ArticleCover");return r(),s("div",null,[o(a,{image:"/assets/covers/tmpa-paper.svg",kicker:"研究论文",title:"TMPA 架构论文",summary:"面向中小企业受治理多智能体组织工作的 AI 原生软件架构理论。",version:"A0.5",status:"学术工作草稿",languageHref:"/en/publications/tmpa-architecture-paper-a0.5",languageLabel:"English"}),t[0]||(t[0]=i(`<h1 id="tmpa-文本化多智能体流程架构" tabindex="-1">TMPA：文本化多智能体流程架构 <a class="header-anchor" href="#tmpa-文本化多智能体流程架构" aria-label="Permalink to &quot;TMPA：文本化多智能体流程架构&quot;">​</a></h1><h2 id="面向中小企业受治理多智能体组织工作的-ai-原生软件架构理论" tabindex="-1">面向中小企业受治理多智能体组织工作的 AI 原生软件架构理论 <a class="header-anchor" href="#面向中小企业受治理多智能体组织工作的-ai-原生软件架构理论" aria-label="Permalink to &quot;面向中小企业受治理多智能体组织工作的 AI 原生软件架构理论&quot;">​</a></h2><blockquote><p><strong>架构论文草稿：</strong> A0.5<br><strong>历史来源基线：</strong> TMPA Draft V1.0-R23；理论已对齐至 R31<br><strong>状态：</strong> 学术工作草稿<br><strong>修订日期：</strong> 2026-08-03<br><strong>出版权威：</strong> 本 GitHub 文档是 TMPA 架构论文的权威版本；独立维护的 TMPA Core Specification 是规范性来源；Implementation Case Report 仅提供工程证据，不具有规范性。</p></blockquote><h1 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h1><p>大语言模型正在从孤立的问答工具转向长期运行、使用工具并由多个智能体共同参与的执行系统。工具调用轨迹与会话历史能够说明发生了什么，却不能仅凭自身确立经过授权的责任归属、合法的生命周期迁移、独立复核或可恢复的治理状态。</p><p>本文提出 <strong>TMPA（Textual Multi-Agent Process Architecture，文本化多智能体流程架构）</strong>：一种面向中小企业、最低基础设施条件的<strong>文本消息多智能体异步流程架构</strong>。其核心由四条相互关联的规则构成：<strong>文本承载持久消息与状态；每个写者保持自己的局部串行流；多条串行流异步推进并形成并行协作；读端聚合现有证据，重建流程、责任、生命周期、冲突与审计状态。</strong> 每一项受治理工作由一个稳定的主载体锚定；后续报告、复核、决策与更正则保持为彼此分离的单写者对象。重建过程保留并发关系与未解决冲突，而不是人为强加一条全局总顺序。</p><p>本文研究的 FCoP 是一种项目可见的文件系统 Profile。它不强制要求协调数据库、消息 Broker 或企业级控制平面，但也不会单独提供经过验证的企业身份、强角色隔离、防篡改存储或拜占庭容错。因此，TMPA 的定位是 <strong>SME-first，而非 SME-only</strong>：规模更大的实现可以通过数据库、对象存储、事件服务、身份系统和控制平面保留同样的治理语义。</p><p>本文采用设计科学方法：从治理缺口与工程谱系推导需求，构造 TMPA 人工制品，分析其不变量和威胁边界，把人工制品映射到 FCoP 参考 Profile，并通过版本锁定的 C01–C14 语料库评估 CodeFlowMu 与现场证据。贡献在于一体化架构，而不是新的存储原语；评价结论严格受证据范围约束。在 I0.6/S0.5 作者运行基线中，<strong>产品级 1 项 PASS、8 项 PARTIAL、3 项 NOT RUN、2 项 FAIL</strong>；独立 Reference Reader 通过 14 项合成标准。现有证据在保留具体实现失败的同时支持结构可行性；完整一致性、低资源性能、采用成本、比较基线、更广泛故障恢复和第三方复现仍是开放的实证要求。</p><p><strong>关键词：</strong> AI 治理、智能体 AI、多智能体系统、中小企业、最低基础设施、文本消息、主载体、单写者流、异步协作、确定性重建、生命周期、角色分离、来源追踪、可审计性、可恢复性、FCoP、CodeFlowMu</p><hr><h1 id="_1-引言" tabindex="-1">1. 引言 <a class="header-anchor" href="#_1-引言" aria-label="Permalink to &quot;1. 引言&quot;">​</a></h1><p>大语言模型已经把人工智能从孤立的推理系统转变为能够调用工具、修改文件、查询数据库、操作业务软件，并在长期任务中协作的执行系统。正确输出仍然是必要条件，但真正可部署的系统还必须保留围绕输出形成的权限、责任与证据。</p><p>一个受治理的多智能体系统必须回答：谁授权并接受了工作，哪个对象代表该项工作，产生了什么证据，谁进行了复核和决策，状态迁移是否合法，以及流程在中断后能否被重新构建。日志、聊天记录、工作流状态与业务记录都可以构成证据的一部分，但它们不会自动形成权威治理状态。</p><p>**TMPA（Textual Multi-Agent Process Architecture）**针对这一缺口提出解决方案，但它不规定智能体如何思考，也不替代 Agent 框架、身份提供方、运行时网关、传输机制或存储系统。TMPA 通过四条运行陈述定义跨平台的流程—责任契约：</p><blockquote><p><strong>文本承载消息与状态。</strong><br><strong>每个写者保持自己的串行流。</strong><br><strong>多条串行流异步推进，形成并行协作。</strong><br><strong>读者聚合各条流并重建流程与治理状态。</strong></p></blockquote><p>每项受治理任务由一个稳定的主载体锚定。接受、报告、复核、决策、更正和恢复证据都是由各自写者独立编写、通过显式引用连接的对象。写入侧保持局部串行与单写者；系统整体异步并行；读取侧则重建偏序图和问题集合。</p><p>本文使用三个定位视图：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计科学谱系</span></span>
<span class="line"><span>业务实践 → 原始 TMPA → FCoP 抽取与成熟</span></span>
<span class="line"><span>         → CodeFlowMu 应用 → 当前 TMPA 形式化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当前概念分层</span></span>
<span class="line"><span>TMPA 架构 → 可复用 FCoP 协议 Profile → CodeFlowMu 与其他下游应用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>端到端流程</span></span>
<span class="line"><span>写入：主载体 → 单写者流 → 异步组合</span></span>
<span class="line"><span>读取：来源聚合 → 治理 Reader → 流程图 + 问题集合</span></span></code></pre></div><p>谱系视图解释其来源，概念关系解释当前边界，流程视图解释系统如何运行。三者都不意味着 FCoP 穷尽了 TMPA、CodeFlowMu 定义了 FCoP，或 2026 年 3 月的早期 Pipeline 已经满足当前 Core Specification。</p><p>第 8.3 节另行说明的一项可选应用场景，是一种跨会话持续存在、业界有时称为<strong>数字员工</strong>的 AI 工作角色。本文使用该名称时，仅指能够接受委托工作、使用工具并跨会话提交结果的工程工作身份；它<strong>不</strong>意味着法律雇佣关系、人格、意识、人类意图，也不意味着替代承担责任的人类或组织主体。</p><h2 id="_1-1-论文类型与研究问题" tabindex="-1">1.1 论文类型与研究问题 <a class="header-anchor" href="#_1-1-论文类型与研究问题" aria-label="Permalink to &quot;1.1 论文类型与研究问题&quot;">​</a></h2><p>本文是一项设计科学与系统架构研究。被设计的人工制品是 TMPA；配套 Core Specification 定义其规范行为，本文负责解释问题、理论、设计逻辑与评价。主要环境是中小企业或小型团队：治理必须能够在没有专用 Agent 平台、协调数据库、消息 Broker、企业身份平面和专业运维团队的情况下开始。FCoP 与 CodeFlowMu 提供实现和演示证据，但本文不声称已有代表性基准、生产规模验证，或优于企业治理平台。</p><p>本文回答三个研究问题：</p><ul><li><strong>RQ1——治理状态充分性：</strong> 当聊天记录、共享目录、执行轨迹和普通任务状态被用作多智能体组织工作的记录时，缺少哪些信息？这些缺失为何会阻止权威责任判断与恢复？</li><li><strong>RQ2——最低架构：</strong> 在不强制协调数据库、Broker 或控制平面的情况下，为了重建受治理多智能体工作，最低需要哪些与基底无关的对象、权限关系、生命周期规则、顺序约束、冲突语义和读取侧操作？</li><li><strong>RQ3——工程可行性与边界：</strong> FCoP Profile、CodeFlowMu、小典 AI 和锁定的 C01–C14 语料库在多大程度上演示了这些性质？哪些可行性声明仍未获得证据支持？</li></ul><p>A0.5 通过证据缺口分析回答 RQ1，通过 TMPA 的对象、流、权限、生命周期与重建模型回答 RQ2。RQ3 只得到边界明确的部分回答：参考 Profile 与案例建立部分可行性；I0.6/S0.5 基线报告产品级 1 项 PASS、8 项 PARTIAL、3 项 NOT RUN、2 项 FAIL [28]。量化安装负担、低资源性能、更广泛故障恢复、比较基线、代表性使用和第三方复现仍未完成。</p><h2 id="_1-2-目标环境与设计约束" tabindex="-1">1.2 目标环境与设计约束 <a class="header-anchor" href="#_1-2-目标环境与设计约束" aria-label="Permalink to &quot;1.2 目标环境与设计约束&quot;">​</a></h2><p>主要目标环境是需要受治理 AI 协作、但缺少以下部分或全部能力的中小企业或小型团队：专用 Agent 平台、协调数据库、消息 Broker、企业 Agent 身份基础设施和专业运维人员。这里的范围以能力约束定义，而不是仅按员工数量定义。</p><p>2026 年 OECD D4SME 调查覆盖 12 个 OECD 国家、2,000 多家中小企业，结果显示战略性且安全的 AI 集成仍不均衡，时间、维护成本与技能缺口依然是实质性障碍 [23]。新加坡 IMDA 报告显示，2024 年中小企业 AI 采用率为 14.5%，而非中小企业为 62.5% [24]。这些来源并不能证明市场对 TMPA 本身的需求；它们支持的是更广泛的问题背景：在组织能力有限时如何负责任地集成 AI。</p><p>这些设计约束推导出如下链条：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础设施与运维能力有限</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>不强制数据库、Broker、集群或控制平面</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>一项受治理任务 → 一个稳定的文本主载体</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>局部串行的单写者责任流</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>各条独立流异步推进</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>来源聚合 → 治理重建</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>可恢复的流程、责任与审计状态</span></span></code></pre></div><blockquote><p><strong>文本承载、局部串行、异步并行、确定性重建。</strong></p></blockquote><p>主要 Profile 是项目本地异步协作，而不是分布式共识或多数据中心执行。参与者不必同时在线，证据可以延迟到达；Reader 根据当前可用集合暴露 authoritative、partial、disputed 或 quarantined 视图。数据库支持和企业级 Profile 仍然可能，但身份联合、复制、高可用和跨信任域强制执行不属于当前验证范围。</p><h2 id="_1-3-设计起源与演化" tabindex="-1">1.3 设计起源与演化 <a class="header-anchor" href="#_1-3-设计起源与演化" aria-label="Permalink to &quot;1.3 设计起源与演化&quot;">​</a></h2><p>TMPA 首次出现于 2026 年 3 月 21 日归档的多角色架构规划第 7.0 节，当时名称为 <strong>Text-Message Multi-AI Parallel Architecture</strong> [25]。原始设计已经把一任务一载体、文件或对象即消息、异步 AI 请求、独立任务线、角色流水线、权限检查和审计轨迹结合起来。</p><p>同一来源也记录了一个过渡性实现：一个 <code>Pipeline</code> 通过共享的 <code>context: dict</code> 顺序推进多个角色，并累积 <code>trace: List[RoleMessage]</code> [25]。因此，该来源证明的是架构起点，而不是今天的 Core 一致性。不可变写者流、保留来源的聚合、确定性重建、显式冲突状态与一致性要求都是后来发展出来的。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>小典 AI 业务实践</span></span>
<span class="line"><span>        ↓ 架构抽象</span></span>
<span class="line"><span>原始 TMPA</span></span>
<span class="line"><span>        ↓ 抽取可复用的文件协调与复核骨架</span></span>
<span class="line"><span>FCoP</span></span>
<span class="line"><span>        ↓ 协议、Schema、Package、MCP、治理与审计演化</span></span>
<span class="line"><span>CodeFlowMu 采用</span></span>
<span class="line"><span>        ↓ 运行反馈</span></span>
<span class="line"><span>当前 TMPA 形式化</span></span></code></pre></div><blockquote><p><strong>实践揭示问题；重复工程发现方法；形式化将方法升华为理论。</strong></p></blockquote><p>本文重新统一了原始的消息与异步模型，以及在 FCoP 和 CodeFlowMu 中成熟的治理语义，同时避免把当前能力追溯性地宣称为早期实现已经具备。</p><h2 id="_1-4-设计前提与贡献" tabindex="-1">1.4 设计前提与贡献 <a class="header-anchor" href="#_1-4-设计前提与贡献" aria-label="Permalink to &quot;1.4 设计前提与贡献&quot;">​</a></h2><p>TMPA 建立在四项前提之上：</p><ol><li><strong>文本化（Textual）：</strong> 治理语义具有可被人、AI 系统与验证器读取的规范表示。</li><li><strong>多智能体（Multi-Agent）：</strong> 执行、复核、批准与监督保持对相互分离的权威主体可归属。</li><li><strong>流程（Process）：</strong> 治理覆盖完整生命周期，包括拒绝、更正、恢复与归档。</li><li><strong>架构（Architecture）：</strong> 这些语义跨模型、Runtime、语言、传输与存储 Profile 保持稳定。</li></ol><p>这些前提产生四项运行承诺：</p><ol><li>持久文本消息与状态载体；</li><li>每项工作一个稳定主载体，每个已发布对象一个写者；</li><li>局部串行与多流异步并行；</li><li>保留来源的聚合，以及随后的确定性治理重建。</li></ol><blockquote><p><strong>写者保持独立，读者重建整体。</strong></p></blockquote><p>TMPA 不声称单独发明了只增历史、生命周期状态机、来源追踪、签名或基于角色的授权。其贡献在于把这些机制集成为最低基础设施流程架构，并使任务身份、责任顺序、生命周期合法性、复核分离、冲突保留、恢复和可机器测试的 Reader 行为成为显式结构。</p><p>本文贡献包括：</p><ol><li>SME-first 架构及其 DR1–DR8 需求集合；</li><li>主载体、单写者、多串行异步写入模型；</li><li>聚合与偏序治理重建契约；</li><li>FCoP 文件 Profile 及其公开工程工件；</li><li>威胁模型、C01–C14 标准与首个版本锁定的一致性基线；</li><li>边界明确的 CodeFlowMu 与小典 AI 证据，以及面向部署、恢复、可检查性、采纳纪律和代表性中小企业负载的实证计划。</li></ol><p>当前 TMPA—FCoP—CodeFlowMu 的关系与运行软件栈在第 4.8 节规定；术语在第 1.5 节固定。</p><h2 id="_1-5-术语与表示阶段" tabindex="-1">1.5 术语与表示阶段 <a class="header-anchor" href="#_1-5-术语与表示阶段" aria-label="Permalink to &quot;1.5 术语与表示阶段&quot;">​</a></h2><p>本文固定以下词汇，以避免把语义对象、物理存储、消息行为与重建视图混为一谈。</p><table tabindex="0"><thead><tr><th>规范英文术语</th><th>固定中文译名</th><th>固定含义</th><th>不等同于</th></tr></thead><tbody><tr><td><strong>governed work item</strong></td><td><strong>受治理工作项</strong></td><td>其责任与生命周期受到治理的任务、请求、决策或流程主题</td><td>一个文件、一个 Session 或一个 Runtime Job</td></tr><tr><td><strong>primary carrier</strong></td><td><strong>主载体</strong></td><td>锚定一项工作标识符和最低治理上下文的稳定治理对象</td><td>所有参与者共同编辑的可变记录</td></tr><tr><td><strong>governance object</strong></td><td><strong>治理对象</strong></td><td>由一个创建者、以一个责任角色、在一条写者流中编写的规范语义单元</td><td>其存储路径、传输封装或派生视图</td></tr><tr><td><strong>textual message</strong></td><td><strong>文本消息</strong></td><td>治理对象在传递工作、证据、复核或决策语义时承担的通信功能</td><td>单独的对象类别或短暂队列消息</td></tr><tr><td><strong>state carrier</strong></td><td><strong>状态载体</strong></td><td>对象、迁移记录或 Profile 规定位置对声明状态或当前状态证据作出贡献的持久化功能</td><td>共享可变应用状态</td></tr><tr><td><strong>source artifact</strong></td><td><strong>来源工件</strong></td><td>证据的一种物理表示或观测，例如文件、数据库行、对象存储项或收到的事件</td><td>验证后的语义治理对象</td></tr><tr><td><strong>source candidate</strong></td><td><strong>来源候选</strong></td><td>提交给聚合阶段的已发现来源工件，包括格式错误或互相冲突的观测</td><td>已接受的权威对象</td></tr><tr><td><strong>canonical candidate set</strong></td><td><strong>规范候选集合</strong></td><td>聚合返回的、保留来源、完成解析、索引与确定性规范化的集合</td><td>最终治理结论</td></tr><tr><td><strong>writer stream</strong></td><td><strong>写者流</strong></td><td>一个可归属写者发布的、局部有序的治理对象序列</td><td>全局 Event Log 或总时间线</td></tr><tr><td><strong>source aggregator</strong></td><td><strong>来源聚合器</strong></td><td>发现、保留、解析、索引与规范化来源候选，但不决定治理真值的阶段</td><td>治理 Reader</td></tr><tr><td><strong>governance reader</strong></td><td><strong>治理 Reader</strong></td><td>把固定 Profile 应用于规范候选集合的确定性阶段</td><td>存储层、编排器或模型 Runtime</td></tr><tr><td><strong>governance graph and issue set</strong></td><td><strong>治理图与问题集合</strong></td><td>重建得到的偏序流程视图，以及规范化的未解决条件输出</td><td>原始来源证据或人为强加的总顺序</td></tr></tbody></table><p>同一个规范治理对象可以通过不同物理 Profile 实现。在 FCoP 中，来源工件通常是文件及其路径与事件证据；其他 Profile 可以使用数据库行、对象或事件。反过来，两个来源工件若声明相同对象 ID、却包含不同的规范内容，它们不是两个无害副本，而是必须被保留并根据 Profile 评估的冲突候选。在架构与规范章节中，**对象（object）**指语义单元，**工件（artifact）**指物理或已发布的工程表示，**视图（view）**指 Reader 派生的结果。</p><hr><h1 id="_2-问题定义与设计需求" tabindex="-1">2. 问题定义与设计需求 <a class="header-anchor" href="#_2-问题定义与设计需求" aria-label="Permalink to &quot;2. 问题定义与设计需求&quot;">​</a></h1><p>TMPA 从区分<strong>执行证据</strong>与<strong>治理证据</strong>开始。运行轨迹可以证明某次工具调用发生过，却不一定能证明调用者获得授权、某个承担责任的角色接受了工作、输出经过独立复核，或者后续批准所引用的正是那份已经复核的结果。聊天记录可以保留讨论，却仍可能缺少稳定对象身份、生命周期合法性、冲突处理与确定性重建。工作流引擎可以记录节点完成，但把权威状态保存在实现专用数据库中。</p><p>因此，该架构区分四类状态：</p><table tabindex="0"><thead><tr><th>状态类别</th><th>主要问题</th></tr></thead><tbody><tr><td>执行状态</td><td>Runtime 正在做什么？</td></tr><tr><td>交互状态</td><td>参与者交换了什么？</td></tr><tr><td>业务状态</td><td>应用当前把什么视为事实？</td></tr><tr><td>治理状态</td><td>哪些责任、迁移、决策、冲突与证据具有权威性？</td></tr></tbody></table><p>TMPA 规范第四类状态，同时允许引用前三类状态。</p><p>文本被选为规范互换形式，是因为人、语言模型、验证器、版本控制工具、备份系统与替代 Runtime 都能够解释它。“文本化”不要求必须采用 Markdown 文件：符合规范的部署可以使用数据库、对象存储或事件服务，只要完整治理含义具有规范文本表示。</p><p>责任分离同样是核心。一套名义上的多智能体系统，如果由同一个身份规划、执行、复核、批准并认证同一项工作，就没有建立独立治理。因此，TMPA 把角色视为具有范围的权威，而不是 Prompt 标签。生命周期也必须显式表达：受治理工作沿 Profile 定义的状态推进；合法迁移、迁移权限、被拒绝的迁移、返工和终态历史都必须保持可观察。</p><p>最低基础设施问题是：</p><blockquote><p>在不预设专用协调数据库、消息 Broker、企业控制平面或专业治理团队的情况下，小型组织如何获得可归属、可复核、可恢复且可由机器检查的多智能体治理？</p></blockquote><p>答案不是孤立地“用文件代替数据库”，而是一套完整流程结构：规范文本承载消息与状态；一个稳定主载体标识每项受治理工作；每个写者通过局部串行流发布；各条独立流异步推进；Reader 重建流程图与问题集合。</p><p>目标是最低基础设施，而不是零纪律。受保护的存储、声明的身份假设、备份、权限、验证与恢复程序仍然必要。OECD 与 IMDA 的证据支持一个更广泛的观察：中小企业长期面对时间、技能、维护与采纳能力约束；这些资料并不证明对 TMPA 本身存在需求 [23]、[24]。</p><p>该问题产生八项可追踪需求：</p><table tabindex="0"><thead><tr><th>ID</th><th>需求</th></tr></thead><tbody><tr><td>DR1</td><td>持久的规范文本表示</td></tr><tr><td>DR2</td><td>稳定工作身份与单写者证据</td></tr><tr><td>DR3</td><td>局部有序流与异步组合</td></tr><tr><td>DR4</td><td>显式权限、复核分离与生命周期合法性</td></tr><tr><td>DR5</td><td>保留来源的聚合与确定性重建</td></tr><tr><td>DR6</td><td>保留冲突、无效证据与部分状态</td></tr><tr><td>DR7</td><td>从持久治理证据恢复</td></tr><tr><td>DR8</td><td>最低强制基础设施与显式保证边界</td></tr></tbody></table><p>DR1–DR7 定义治理语义。DR8 约束部署声明：TMPA 尽量降低协调基础设施要求，但不会继承实际未部署的身份、安全、共识或控制平面系统所提供的保证。</p><hr><h1 id="_3-相关工作与定位" tabindex="-1">3. 相关工作与定位 <a class="header-anchor" href="#_3-相关工作与定位" aria-label="Permalink to &quot;3. 相关工作与定位&quot;">​</a></h1><p>TMPA 位于 Agent 执行层与企业治理层之间的流程—责任层。MCP 与 A2A 解决工具使用和 Agent 互操作 [1]、[2]；身份系统建立主体与委托权限 [19]；网关与策略引擎负责运行时准入；可观测性与控制平面产品盘点 Agent 并收集遥测。TMPA 不替代这些层，而是接收它们提供的标识符、策略决策、轨迹与工件，并把受治理工作、复核、拒绝、恢复与责任表示为可重建形式。</p><h2 id="_3-1-架构前身" tabindex="-1">3.1 架构前身 <a class="header-anchor" href="#_3-1-架构前身" aria-label="Permalink to &quot;3.1 架构前身&quot;">​</a></h2><p>Event Sourcing 与 CQRS 提供面向追加的历史，以及写入表示与读取模型的分离 [4]。Git 展示了不可变的内容寻址对象和显式历史 [5]。W3C PROV 提供实体、活动、Agent 与派生关系 [3]。TMPA 建立在这些思想之上，但增加更窄且更明确的流程治理契约：每项工作一个主载体、单写者责任流、显式生命周期权限、职责分离、冲突保留，以及确定性治理 Reader。</p><p>该架构不等同于聊天记录、共享目录、ADR 集合、工作流引擎或单一全局 Event Log。这些机制可以保存相关证据，但它们本身不定义哪个对象具有权威性、某项行为是否在授权范围内、复核是否独立，以及互相矛盾的证据应如何保持可见。</p><h2 id="_3-2-互操作与治理缺口" tabindex="-1">3.2 互操作与治理缺口 <a class="header-anchor" href="#_3-2-互操作与治理缺口" aria-label="Permalink to &quot;3.2 互操作与治理缺口&quot;">​</a></h2><p>Agentic AI Foundation 的成立反映了围绕 MCP 及相关项目的互操作基础设施正在增长 [6]。但互操作并不等同于治理。Kang 与 Diponegoro 使用成员资格、审议、投票、异议保留、人工升级和审计/回放等需求，对 MCP、A2A、ACP、ANP 和 ERC-8004 进行分析，发现所调查协议均未表达完整治理模型 [27]。TMPA 处理其中更窄的子集——工作责任、生命周期、复核、冲突与恢复——而不是完整的社群治理。</p><p>《Open Challenges in Multi-Agent Security》强调，即使单个组件看似安全，共谋、级联效应、隐蔽行为与监督失败仍可能在交互层出现 [26]。TMPA 可以保留可归属证据和未解决分歧以供调查，但它不是共谋检测器。</p><h2 id="_3-3-直接相邻研究" tabindex="-1">3.3 直接相邻研究 <a class="header-anchor" href="#_3-3-直接相邻研究" aria-label="Permalink to &quot;3.3 直接相邻研究&quot;">​</a></h2><p><strong>Auditable Agents</strong> 区分 accountability、auditability 与 auditing，并从行为可恢复性、生命周期覆盖、策略可检查性、责任归属和证据完整性五个维度进行评估 [17]。TMPA 与其互补：TMPA 规定持久工作对象与流程重建，使这些维度能够被评估。</p><p>IETF Agent 审计架构同样把委托与交互视为可审计事件 [18]。TMPA 可以为这些事件提供项目本地或平台中立表示，但不标准化网络传输。</p><p><strong>Authorization Propagation in Multi-Agent AI Systems</strong> 把传递式委托、权限聚合推断与时间有效性识别为尚未解决的授权问题 [20]。TMPA 记录任务分配和责任迁移，但不定义完整的递归委托演算。</p><p><strong>Policies on Paths</strong> 主张运行时治理可能取决于部分执行路径，而不是静态访问规则 [21]。TMPA 把流程路径保留为证据，但自身不负责在执行期间阻断行为。</p><p><strong>Proof-Carrying Agent Actions</strong> 把高价值动作与决策时证书、批准和可回放证明绑定 [29]。PCAA 以动作决策为中心；TMPA 以更长期的受治理工作项及其报告、复核、冲突、更正和恢复为中心。TMPA Profile 可以引用 PCAA 证书作为执行证据。</p><p><strong>AGENTSAFE</strong> 结合风险分类、语义遥测、动态授权、可中断性、异常检测、密码学追踪和组织控制 [30]。TMPA 选择不同的最低基线：可读的规范文本与确定性重建是强制要求，而密码学身份与更强完整性控制属于可选的命名 Profile。</p><p><strong>Why Do Multi-Agent LLM Systems Fail?</strong> 从大规模轨迹语料中归纳失败类别 [22]。TMPA 改善责任、复核、冲突和恢复的可观察性，但本文不声称已降低失败率。</p><p>因此，增量贡献不是新的存储原语，也不是完整控制平面，而是把以下结构组合起来：持久文本消息/状态平面、一任务一主载体、局部单写者流、异步组合、保留来源的聚合，以及最低基础设施 Profile 下的确定性读端治理重建。</p><h2 id="_3-4-比较综合与研究缺口" tabindex="-1">3.4 比较综合与研究缺口 <a class="header-anchor" href="#_3-4-比较综合与研究缺口" aria-label="Permalink to &quot;3.4 比较综合与研究缺口&quot;">​</a></h2><p>相关工作可以归入五条相邻研究线。它们的边界共同说明 TMPA 所处理的缺口：</p><table tabindex="0"><thead><tr><th>研究线</th><th>主要贡献</th><th>与 TMPA 的关系及边界</th></tr></thead><tbody><tr><td>MCP 与 A2A [1]、[2]</td><td>面向工具或 Agent 交互的 Context、Capability、Task 与消息互操作交换</td><td>TMPA 可以引用这些交互，但定义持续时间更长的责任、复核、冲突与恢复证据</td></tr><tr><td>W3C PROV、Event Sourcing 与 CQRS [3]、[4]</td><td>派生、面向追加的事件历史与读取模型构造</td><td>TMPA 把这些机制专门化为受治理工作身份、权限、生命周期合法性和确定性问题重建</td></tr><tr><td>Auditable Agents 与 IETF 审计架构 [17]、[18]</td><td>问责维度、分布式审计记录、上下文与事后调查</td><td>TMPA 提供基底中立的受治理工作图，但不定义网络审计上下文传播或证明机制</td></tr><tr><td>授权传播、路径策略与携证动作 [20]、[21]、[29]</td><td>面向委托路径或带证书动作的决策时授权与运行时强制</td><td>TMPA 保留已授权工作过程及其结果，不替代执行时中介</td></tr><tr><td>NIST AI RMF 与 AGENTSAFE [30]、[31]</td><td>组织风险识别、控制、监测、保证与问责</td><td>TMPA 是可以支持这些计划的较窄证据架构，不构成完整风险管理框架</td></tr></tbody></table><p>在本文审查的相邻研究中，没有一项把以下全部性质合并为同一个最低基础设施流程契约：稳定主载体、单写者责任流、不强制总顺序的异步组合、显式权限与生命周期语义、无效和冲突证据保留，以及治理图与问题集合的确定性重建。这是 A0.5 主张的特定研究缺口。该主张是架构性与比较性的，不是对所有未公开或专有系统的优先权声明。</p><hr><h1 id="_4-tmpa-架构" tabindex="-1">4. TMPA 架构 <a class="header-anchor" href="#_4-tmpa-架构" aria-label="Permalink to &quot;4. TMPA 架构&quot;">​</a></h1><p>TMPA 定义治理语义，而不是一个 Runtime 组件。其架构规定哪些治理事实必须被表示、责任与生命周期如何表达，以及如何把独立证据重建为权威视图。除非某个 TMPA Profile 明确绑定，否则存储、传输、调度和模型行为仍属于实现问题。</p><h2 id="_4-1-治理对象" tabindex="-1">4.1 治理对象 <a class="header-anchor" href="#_4-1-治理对象" aria-label="Permalink to &quot;4.1 治理对象&quot;">​</a></h2><p><strong>治理对象（governance object）<strong>是 TMPA 中最小的、能够独立归属责任的语义单元。它可以表示任务、报告、复核、批准、问题、生命周期迁移、角色分配、恢复动作，或协议 Profile 发布的其他文档类型。治理对象不同于其物理</strong>来源工件（source artifact）</strong>：FCoP 可以把它编码为文件以及路径观测，其他 Profile 可以采用数据库行、对象存储项或事件。</p><p><strong>文本消息</strong>和<strong>状态载体</strong>描述的是对象承担的功能，而不是额外对象类别。对象在传递受治理工作或证据时承担文本消息功能；当其内容、迁移证据或 Profile 规定的位置参与生命周期重建时，则承担状态载体功能。</p><p>每个治理对象包含或标识：</p><ul><li>稳定对象 ID；</li><li>文档类型；</li><li>一个创建者身份；</li><li>一个责任角色；</li><li>流 ID 与序号；</li><li>创建时间；</li><li>生命周期 Profile 与声明状态；</li><li>指向相关对象的类型化引用；</li><li>规范文本内容；</li><li>完整性证据。</li></ul><p>已发布治理对象不可变。更正不会删除或重写原对象，而是创建一个新的对象，以取代、拒绝、限定或解决先前对象。多个字节完全相同的来源观测可以指向同一个对象而不改变其含义；同一 ID 对应不同规范内容则构成冲突，而不是更新。</p><p>对象声明的生命周期状态，是该对象发布时按照其 Profile 关联的状态。受治理工作的当前权威状态从有效对象集合、已接受迁移和 Profile 规则中重建，而不是通过修改先前对象或选择时间戳最新的对象获得。</p><h2 id="_4-2-文档类型" tabindex="-1">4.2 文档类型 <a class="header-anchor" href="#_4-2-文档类型" aria-label="Permalink to &quot;4.2 文档类型&quot;">​</a></h2><p>TMPA Core 不强制统一的业务文档分类。每个实现 Profile 发布一个有限的文档类型注册表。</p><p>每条注册项定义：</p><ul><li>类型名称与版本；</li><li>该类型代表的治理责任；</li><li>允许的创建者角色；</li><li>必填字段；</li><li>允许的引用关系；</li><li>适用生命周期 Profile；</li><li>验证规则。</li></ul><p>不同文档类型的权威含义不得产生歧义重叠。例如，执行报告不会自动同时成为自身的独立复核或批准。当部署允许职责分离例外时，例外本身及其批准权威必须被显式表示。</p><h2 id="_4-3-角色与权限模型" tabindex="-1">4.3 角色与权限模型 <a class="header-anchor" href="#_4-3-角色与权限模型" aria-label="Permalink to &quot;4.3 角色与权限模型&quot;">​</a></h2><p>TMPA 角色是在明确范围内具有治理权限的权威主体，而不只是 Prompt 标签或自然语言 Persona。</p><p>每项角色定义包括：</p><ul><li>稳定角色 ID；</li><li>允许创建的对象类型；</li><li>允许执行的生命周期动作；</li><li>职责分离约束；</li><li>分配该角色的权威；</li><li>角色分配的有效期与撤销状态。</li></ul><p>对象中的 <code>role</code> 字段声明创建者以何种权威行动，但该字段不会自行创造权限。Reader 必须根据有效角色分配和适用策略 Profile 验证该声明。</p><p>只有实现 Profile 明确允许时，一个参与者才能同时占据多个角色。声称具备独立复核的部署，必须禁止同一身份对同一受治理结果同时担任执行者和复核者，除非存在经过记录且获得授权的例外。</p><p>在企业身份 Profile 中，逻辑角色还需分别绑定到：可验证的 Agent 或工作负载身份、继续承担责任的人类或组织主体、此次动作使用的凭证、委托来源与范围，以及有效或撤销状态。TMPA Core 记录并验证治理声明，但不签发凭证，也不强制执行递归权限衰减。</p><h2 id="_4-4-生命周期模型" tabindex="-1">4.4 生命周期模型 <a class="header-anchor" href="#_4-4-生命周期模型" aria-label="Permalink to &quot;4.4 生命周期模型&quot;">​</a></h2>`,112))])}const b=n(l,[["render",p]]);export{u as __pageData,b as default};
